import java.util.*;class Solution{public List<List<Integer>> verticalOrder(TreeNode r){List<List<Integer>>o=new ArrayList<>();if(r==null)return o;Map<Integer,List<Integer>>m=new TreeMap<>();Queue<TreeNode>q=new ArrayDeque<>();Queue<Integer>c=new ArrayDeque<>();q.add(r);c.add(0);while(!q.isEmpty()){TreeNode n=q.remove();int x=c.remove();m.computeIfAbsent(x,z->new ArrayList<>()).add(n.val);if(n.left!=null){q.add(n.left);c.add(x-1);}if(n.right!=null){q.add(n.right);c.add(x+1);}}o.addAll(m.values());return o;}}
